#!/usr/bin/env python3
# Assemble Sumner_mathlib.lean: header, generated data, checkers, soundness
# glue, and the per-n kernel checks plus the final theorem.
# Usage: build_lean.py N DATA.lean > Sumner_mathlib.lean
#
import sys, os
N = int(sys.argv[1])
M = 2*N - 2
here = os.path.dirname(os.path.abspath(__file__))
part = lambda f: open(os.path.join(here, "parts", f)).read()
names = {2: "two", 3: "three", 4: "four", 5: "five", 6: "six"}

out = [part("header.lean").replace("@N@", str(N)).replace("@M@", str(M)),
       "/-! ## Data (generated by scripts/gen_lean.py) -/\n",
       open(sys.argv[2]).read(), part("comp.lean"), part("glue.lean"),
       "/-! ## Kernel checks -/\n"]
from gen import build
reps, _ = build(M)
CH = {7: (19, 24)}
EM = {5: (20, 344)}
def chunked(name, count, body, C, L):
  assert C * L == count
  for c in range(C):
    out.append(f"theorem {name}_c{c} : allLT {L} (fun j => {body} ({c} * {L} + j)) = true := by decide +kernel\n")
  out.append(f"""theorem {name} : allLT {count} ({body}) = true := by
  rw [show {count} = {C} * {L} from rfl]
  apply allLT_mul
  intro c hc
  interval_cases c
""" + "\n".join(f"  · exact {name}_c{c}" for c in range(C)) + "\n")
for k in range(1, M):
  if k in CH:
    chunked(f"step_{k}", len(reps[k]), f"stepBody {k}", *CH[k])
    out.append(f"theorem step_{k}' : allLT (numReps {k}) (stepBody {k}) = true := step_{k}\n")
  else:
    out.append(f"theorem step_{k}' : allLT (numReps {k}) (stepBody {k}) = true := by decide +kernel\n")
out.append("theorem classified_1 : Classified 1 := classified_one\n")
for k in range(2, M+1):
  out.append(f"theorem classified_{k} : Classified {k} := classified_succ classified_{k-1} step_{k-1}'\n")
for n in range(2, N+1):
  m = 2*n - 2
  if n in EM:
    chunked(f"emb_{n}_raw", len(reps[m]), f"embBody {n} {m}", *EM[n])
    out.append(f"theorem emb_{n} : allLT (numReps {m}) (embBody {n} {m}) = true := emb_{n}_raw\n")
  else:
    out.append(f"theorem emb_{n} : allLT (numReps {m}) (embBody {n} {m}) = true := by decide +kernel\n")
  out.append(f"theorem codes_{n} : codesOK {n} = true := by decide +kernel\n")
out.append(f"""/-- **Sumner's universal tournament conjecture for trees on at most {N} vertices**:
every tournament on `2n - 2` vertices contains every oriented tree on `n` vertices,
for `2 ≤ n ≤ {N}` (statement shape and definitions as in formal-conjectures). -/
theorem sumner_le_{names[N]} : ∀ (n : ℕ), 2 ≤ n → n ≤ {N} →
    ∀ {{W : Type}} [Fintype W] [DecidableEq W] (D : Digraph W) [DecidableRel D.Adj],
      Fintype.card W = n → IsOrientedTree D →
      ∀ {{V : Type}} [Fintype V] [DecidableEq V] (G : Digraph V) [DecidableRel G.Adj],
        Fintype.card V = 2 * n - 2 → IsTournament G → Embeds D G := by
  intro n h2 hN W _ _ D _ hW hD V _ _ G _ hV hG
  interval_cases n""")
for n in range(2, N+1):
  m = 2*n - 2
  out.append(f"  · exact sumner_of_checks {n} {m} (by norm_num) rfl classified_{m} emb_{n} codes_{n} D hW hD G hV hG")
import re
text = "\n".join(out)
head, body = text.split("/-! ## Data", 1)
body = re.sub(r"^(noncomputable def|def|theorem|structure) (?!SumnerSmall\.)", r"\1 SumnerSmall.", "/-! ## Data" + body, flags=re.M)
print(head + body)
